import sys
sys.path.insert(0,'/tmp')
from harness import *
import struct
def s(b):
    if isinstance(b,str): b=b.encode()
    return bytes([len(b)])+b

def case(name, rtype, rdata, sections='answers'):
    def h(q):
        kw={sections:[rr(PTR, rtype, 1, 300, rdata)]}
        return build_response(q, **kw)
    with Server(h) as srv:
        args=["example.net","@127.0.0.1:15353"]
        for extra in [[], ["-J"], ["-1"], ["--edns=show"], ["--edns=show","-J"], ["--edns=hide"], ["--edns=hide","-J"], ["--edns=disable"], ["--edns=disable","-J"]]:
            p=run_dog(args+extra)
            print(name, sections, extra, "exit", p.returncode, "out", p.stdout, "err", p.stderr)

# OPT in additionals: name root, type 41, class = 4096 (udp size), ttl = extended rcode etc, rdata options
# rr() function uses name/rtype/class/ttl... need custom: name=b'\x00', type41, class 4096, ttl 0, rdata option: code 3 (NSID?) ...
opt_rdata=struct.pack('>HH',3,4)+b'abcd'
opt_rr=rr(b'\x00',41,4096,0,opt_rdata)
def h_opt(q):
    return build_response(q, answers=[rr(PTR,1,1,300,socket.inet_aton('1.2.3.4'))], additionals=[opt_rr])
with Server(h_opt) as srv:
    args=["example.net","@127.0.0.1:15353"]
    for extra in [[], ["-J"], ["-1"], ["--edns=show"], ["--edns=show","-J"], ["--edns=hide"], ["--edns=hide","-J"], ["--edns=disable"], ["--edns=disable","-J"]]:
        p=run_dog(args+extra)
        print("OPT-in-additional", extra, "exit", p.returncode, "out", p.stdout, "err", p.stderr)
    print("queries extra:", [q['extra'] for q in srv.queries])

# OPT alone in additionals no answers
def h_opt2(q):
    return build_response(q, additionals=[opt_rr])
with Server(h_opt2) as srv:
    args=["example.net","@127.0.0.1:15353"]
    for extra in [[], ["-J"], ["-1"], ["--edns=show"], ["--edns=show","-J"]]:
