    if t==6: return encode_name("m.example")+encode_name("r.example")+struct.pack('>IIIII',1,2,3,4,5)
    if t==13: return b'\x01a\x01b'
    if t==15: return struct.pack('>H',1)+encode_name("x.example")
    if t==16: return b'\x01a'
    if t==29: return bytes([0,0,0,0])+struct.pack('>III',2147483648,2147483648,10000000)
    if t==33: return struct.pack('>HHH',1,2,3)+encode_name("x.example")
    if t==35: return struct.pack('>HH',1,2)+b'\x01f\x01s\x01r'+encode_name("x.example")
    if t==41: return b''
    if t==44: return b'\x01\x02\xab'
    if t==52: return b'\x01\x02\x03\xab'
    if t==61: return b'\x01'
    if t==108: return bytes(6)
    if t==109: return bytes(8)
    if t==256: return struct.pack('>HH',1,2)+b'a'
    if t==257: return bytes([0,1])+b'a'+b'b'
    return b'\x01\x02\x03\x04'
import struct
