import socket, threading, subprocess, sys
sys.path.insert(0,'/tmp')
from harness import *
# IPv6 UDP server
srv6=socket.socket(socket.AF_INET6, socket.SOCK_DGRAM)
try:
    srv6.bind(('::1',15353)); print("v6 bound")
except Exception as e: print("v6 bind fail",e)
srv6.settimeout(5)
def serve6():
    try:
        data,addr=srv6.recvfrom(4096); print("v6 got",data,addr)
        q=parse_query(data); resp=build_response(q, answers=[rr(b'\xc0\x0c',1,1,300,socket.inet_aton('9.9.9.9'))])
        srv6.sendto(resp,addr)
    except Exception as e: print("v6 err",e)
t=threading.Thread(target=serve6,daemon=True); t.start()
def h4(q): return build_response(q, answers=[rr(PTR,1,1,300,socket.inet_aton('1.2.3.4'))])
with Server(h4, port=15353) as s4:
    for ns in ["@localhost:15353","@localhost"]:
        # For port default case, v6 and v4 servers on 53? can't? Let's just test port case, and t timeout
        p=subprocess.run(["./executable","example.net",ns], capture_output=True, timeout=5)
        print(ns,p.returncode,p.stdout,p.stderr)
    t.join(timeout=2)
PY"}

