# ---------- Record types / classes ----------
# interpreted types (unit variants)
INTERPRETED = {
    1:"A",2:"NS",5:"CNAME",6:"SOA",12:"PTR",13:"HINFO",15:"MX",16:"TXT",
    28:"AAAA",29:"LOC",33:"SRV",35:"NAPTR",44:"SSHFP",52:"TLSA",61:"OPENPGPKEY",
    108:"EUI48",109:"EUI64",256:"URI",257:"CAA",
}
HEARD_OF = {
    17:"RP",18:"AFSDB",24:"SIG",25:"KEY",36:"KX",37:"CERT",39:"DNAME",42:"APL",43:"DS",
    45:"IPSECKEY",46:"RRSIG",47:"NSEC",48:"DNSKEEYE",49:"DHCID",50:"NSEC3",51:"NSEC3PARAM",
    53:"SMIMEA",55:"HIP",59:"CDS",60:"CDNSKEY",62:"CSYNC",249:"TKEY",250:"TSIG",251:"IXFR",
    252:"AXFR",255:"ANY",32768:"TA",32769:"DLV",
}
NAME_TO_TYPE = {}
for num,name in INTERPRETED.items(): NAME_TO_TYPE[name]=num
for num,name in HEARD_OF.items(): NAME_TO_TYPE[name]=num
NAME_TO_TYPE["OPT"]=41

def type_repr_debug(num):
    if num in INTERPRETED:
        return INTERPRETED[num]
    if num in HEARD_OF:
        return f'Other(HeardOf("{HEARD_OF[num]}", {num}))'
    return f'Other(UnheardOf({num}))'

def type_display(num):
    # for human/JSON display of response/query types
    if num in INTERPRETED:
        return INTERPRETED[num]
    if num in HEARD_OF:
        return HEARD_OF[num]
    if num==41:
        return "OPT"
    return None  # numeric

CLASS_NAMES={1:"IN",3:"CH",4:"HS"}
NAME_TO_CLASS={"IN":1,"CH":3,"HS":4}

def parse_query_type(s):
    # returns int type or raises OptionsError with message (without prefix?)
    # OPT special
    # Uppercase: Rust? Use unicode uppercase
    up=s.upper()
    if up=="OPT":
        raise OptionsError('OPT request is sent by default (see -Z flag)')
    v=rust_u16_parse(s)
    if v is not None:
        return v
    if up in NAME_TO_TYPE:
        return NAME_TO_TYPE[up]
    raise OptionsError(f'Invalid query type {rust_debug_str(s)}')

def parse_query_class(s):
    v=rust_u16_parse(s)
    if v is not None:
        return v
    up=s.upper()
    if up in NAME_TO_CLASS:
        return NAME_TO_CLASS[up]
    raise OptionsError(f'Invalid query class {rust_debug_str(s)}')

# ---------- Domain / IDNA ----------
IGNORED_CHARS = {
    '\u00ad','\u034f','\u061c','\u115f','\u1160','\u17b4','\u17b5',
    '\u180b','\u180c','\u180d','\u180f','\u200b','\u2060','\u2064',
    '\u3164','\ufeff','\uffa0',
}
# variation selectors fe00-fe0f handled as range

def idna_convert_label(label):
    # returns (converted_str, error_list or None)
    # Check disallowed characters (approximate)
    # Characters that Rust idna crate would report DissallowedCharacter
    disallowed=False
