# ---------- Domain / IDNA ----------
IGNORED_CHARS = {
    '\u00ad','\u034f','\u061c','\u115f','\u1160','\u17b4','\u17b5',
    '\u180b','\u180c','\u180d','\u180f','\u200b','\u2060','\u2064',
    '\u3164','\ufeff','\uffa0',
}
# variation selectors fe00-fe0f handled as range

def idna_convert_label(label):
    # returns (converted_str, error_list or None)
    # Check disallowed characters (approximate)
    # Characters that Rust idna crate would report DissallowedCharacter
    disallowed=False
    for ch in label:
        o=ord(ch)
        if ch in ('\u202e','\u202a','\u202b','\u202c','\u202d','\u2024','\ufffc','\ufffd'):
            disallowed=True
        elif o>=0xFFF0 and o<=0xFFFF: # noncharacters / specials
            disallowed=True
        elif 0xFDD0 <= o <= 0xFDEF:
            disallowed=True
        elif (o & 0xFFFE)==0xFFFE: # noncharacter ..FFFE/FFFF
            disallowed=True
        elif unicodedata.category(ch)=='Cs':
            disallowed=True
    # Special case: label containing U+2024 etc -> disallowed
    # Mapping step
    # protect deviations
    # Process char by char
    mapped_chars=[]
    for ch in label:
        if ch in ('\u3002','\uff0e','\uff61'):
            mapped_chars.append('.')
        elif ch=='\u00df' or ch=='\u1e9e': # ß capital sharp -> ß (UTS46 nontransitional) ; casefold would give ss, manually keep ß
            mapped_chars.append('\u00df')
        elif ch=='\u03c2': # final sigma keep
            mapped_chars.append('\u03c2')
        elif ch in ('\u200c','\u200d'):
            mapped_chars.append(ch)
        elif ch in IGNORED_CHARS or (0xFE00 <= ord(ch) <= 0xFE0F) or (0x180B <= ord(ch) <= 0x180D):
            # ignored / map to nothing
            continue
        else:
            mapped_chars.append(ch)
    mapped=''.join(mapped_chars)
    # case fold then NFKC then NFC, preserving protected ß/ς/ZWJ/NJ
    # Use placeholder to protect
    placeholders={}
    def protect(s, chars):
        for i,ch in enumerate(chars):
            ph=chr(0xE000+i)  # private use, will be restored; NFKC might alter? private use preserved by NFKC
            placeholders[ph]=ch
            s=s.replace(ch, ph)
        return s
    protected = protect(mapped, ['\u00df','\u03c2','\u200c','\u200d'])
    folded = protected.casefold()
    # casefold may transform placeholders? no
    compat = unicodedata.normalize('NFKC', folded)
    restored=compat
    for ph,ch in placeholders.items():
        restored=restored.replace(ph, ch)
    normalized = unicodedata.normalize('NFC', restored)
    # After normalization, if characters are disallowed according to category? e.g. controls for non-ascii etc.
    # Determine converted label
    if all(ord(c)<128 for c in normalized):
        converted=normalized
    else:
        # punycode
        try:
            puny=normalized.encode('punycode').decode('ascii')
        except Exception:
            disallowed=True
            puny=""
        converted="xn--"+puny if puny else "xn--"
    errors=[]
    if disallowed:
        errors.append("DissallowedCharacter")
        errors.append("ValidityCriteria")
    else:
        # validity: starts/ends with '-' (check original? or normalized?) - use normalized first/last char
        # Also label starts with combining mark (category M)
        validity=False
        if normalized.startswith('-') or normalized.endswith('-'):
            validity=True
        if normalized and unicodedata.category(normalized[0]).startswith('M'):
            validity=True
        # Hyphen in 3rd and 4th positions not xn-- ? UTS46 validity: if label has '-' in positions 3-4 and not punycode; but original xn-- labels are allowed? Skip
        if validity:
            errors.append("ValidityCriteria")
    if len(converted.encode('utf-8'))>63:
        if "TooLongForDns" not in errors:
            errors.append("TooLongForDns")
    if errors:
        return (None, errors)
    return (converted, None)

class Labels:
    def __init__(self, segments):
        self.segments=segments # list of strings (converted)
    def to_string(self):
        if not self.segments:
            return ""
        return ".".join(self.segments)+"."
    def __repr__(self):
        return f"Labels({self.segments})"

def parse_domain(s):
    # returns Labels or raises OptionsError Invalid domain "..."
    # Split on ASCII dot
    parts=s.split('.')
    segments=[]
    for part in parts:
        if part=="":
            continue
        converted, errors = idna_convert_label(part)
        if errors is not None:
            LOG.warn("dns::strings", f"Could not encode label {rust_debug_str(part)}: Errors({errors})")
            raise OptionsError(f'Invalid domain {rust_debug_str(s)}')
        segments.append(converted)
    return Labels(segments)

def domain_from_labels_bytes(labels_bytes_list):
    # labels_bytes_list: list of bytes
    segs=[]
    for b in labels_bytes_list:
        segs.append(b.decode('utf-8', errors='replace'))
    return Labels(segs)

# ---------- Getopts ----------
class OptDef:
    def __init__(self, short, longname, has_arg, occur):
        self.short=short; self.long=longname; self.has_arg=has_arg; self.occur=occur # 'single','multi','flag','flagmulti' but we use counts
    def canonical(self):
        return self.long if self.long else self.short

OPT_DEFS=[
    OptDef('q','query',True,'multi'),
    OptDef('t','type',True,'multi'),
    OptDef('n','nameserver',True,'multi'),
    OptDef(None,'class',True,'multi'),
    OptDef(None,'edns',True,'single'),
    OptDef(None,'txid',True,'single'),
    OptDef('Z','',True,'multi'), # long empty? but --Z works via short matching
    OptDef('U','udp',False,'flag'),
    OptDef('T','tcp',False,'flag'),
    OptDef('S','tls',False,'flag'),
    OptDef('H','https',False,'flag'),
    OptDef('1','short',False,'flag'),
    OptDef('J','json',False,'flag'),
    OptDef(None,'color',True,'single'),
    OptDef(None,'colour',True,'single'),
    OptDef(None,'seconds',False,'flag'),
    OptDef(None,'time',False,'flag'),
    OptDef('?','help',False,'flag'),
    OptDef('v','version',False,'flag'),
]
def find_long(name):
    for d in OPT_DEFS:
        if d.long and d.long==name:
            return d
        if len(name)==1 and d.short==name:
            return d
    return None
def find_short(ch):
    for d in OPT_DEFS:
        if d.short==ch:
            return d
    return None

class GetoptsResult:
    def __init__(self):
        self.occurs={} # id(def) -> list of values or count for flags ; we key by canonical unique per def object index
        self.free=[]
    def add(self, defi, value):
        self.occurs.setdefault(id(defi), []).append(value)
    def present(self, defi):
        return id(defi) in self.occurs
    def count(self, defi):
        return len(self.occurs.get(id(defi),[]))
    def values(self, defi):
        return self.occurs.get(id(defi),[])
    def opt_str(self, defi):
        v=self.values(defi)
        return v[0] if v else None

def def_by_long(longname):
    for d in OPT_DEFS:
        if d.long==longname: return d
    return None
def def_by_short(s):
    for d in OPT_DEFS:
        if d.short==s: return d
    return None

def parse_getopts(args_str):
    # args_str list of str
    res=GetoptsResult()
    i=0
    end_opts=False
    while i < len(args_str):
        arg=args_str[i]
        if end_opts:
            res.free.append(arg); i+=1; continue
        if arg=="--":
            end_opts=True; i+=1; continue
        elif arg.startswith("--") and len(arg)>2:
            body=arg[2:]
            if "=" in body:
                name, value = body.split("=",1); has_value=True
            else:
                name, value, has_value = body, None, False
            defi=find_long(name)
            if defi is None:
                raise OptionsError(f"Unrecognized option: '{name}'")
            if not defi.has_arg:
                if has_value:
                    raise OptionsError(f"Option '{name}' does not take an argument")
                # flag occurrence check
                if defi.occur=='flag' and res.present(defi):
                    raise OptionsError(f"Option '{defi.canonical()}' given more than once")
                res.add(defi, True)
                i+=1; continue
            else:
                # takes arg
                if has_value:
                    val=value
                else:
                    if i+1>=len(args_str):
                        raise OptionsError(f"Argument to option '{name}' missing")
                    i+=1; val=args_str[i]
                if defi.occur=='single' and res.present(defi):
                    raise OptionsError(f"Option '{defi.canonical()}' given more than once")
                res.add(defi, val)
                i+=1; continue
        elif arg.startswith("-") and len(arg)>1:
            # short cluster
            chars=list(arg[1:])
            j=0
            consumed_next=False
            while j < len(chars):
                ch=chars[j]
                defi=find_short(ch)
                if defi is None:
                    raise OptionsError(f"Unrecognized option: '{ch}'")
                if not defi.has_arg:
                    if defi.occur=='flag' and res.present(defi):
                        raise OptionsError(f"Option '{defi.canonical()}' given more than once")
                    res.add(defi, True)
                    j+=1; continue
                else:
                    # takes arg
                    if j+1 < len(chars):
                        val=''.join(chars[j+1:])
                    else:
                        if i+1>=len(args_str):
                            raise OptionsError(f"Argument to option '{ch}' missing")
                        consumed_next=True; val=args_str[i+1]
                    if defi.occur=='single' and res.present(defi):
                        raise OptionsError(f"Option '{defi.canonical()}' given more than once")
                    res.add(defi, val)
                    break
            i+= 2 if consumed_next else 1
            continue
        else:
            res.free.append(arg); i+=1; continue
    return res

