# ---------- Pretty Debug for Options (Rust {:#?}) ----------
def rust_pretty(value, indent):
    # value is a tuple representing Rust debug structure
    # We implement via custom Node objects
    raise NotImplementedError

class Dbg:
    pass
class DStruct(Dbg):
    def __init__(self, name, fields): self.name=name; self.fields=fields # list of (k, Dbg)
class DList(Dbg):
    def __init__(self, items): self.items=items
class DTuple(Dbg):
    def __init__(self, items): self.items=items
class DVariant(Dbg):
    # enum: name, optional tuple values or struct? For tuple variant with values, for unit variant values=None
    def __init__(self, name, values=None): self.name=name; self.values=values
class DLeaf(Dbg):
    def __init__(self, text): self.text=text

def format_dbg(node, indent):
    # returns string without trailing comma; indent is current indentation level (number of spaces for closing)
    pad=' '*indent
    pad_inner=' '*(indent+4)
    if isinstance(node, DLeaf):
        return node.text
    if isinstance(node, DStruct):
        if not node.fields:
            return f"{node.name} {{}}"
        parts=[f"{node.name} {{"]
        for k,v in node.fields:
            fv=format_dbg(v, indent+4)
            parts.append(f"{pad_inner}{k}: {fv},")
        parts.append(f"{pad}}}")
        return "\n".join(parts)
    if isinstance(node, DList):
        if not node.items:
            return "[]"
        parts=["["]
        for it in node.items:
            fv=format_dbg(it, indent+4)
            parts.append(f"{pad_inner}{fv},")
        parts.append(f"{pad}]")
        return "\n".join(parts)
    if isinstance(node, DTuple):
        if not node.items:
            return "()"
        parts=["("]
        for it in node.items:
            fv=format_dbg(it, indent+4)
            parts.append(f"{pad_inner}{fv},")
        parts.append(f"{pad})")
        return "\n".join(parts)
    if isinstance(node, DVariant):
        if node.values is None:
            return node.name
        # tuple variant
        if len(node.values)==0:
            return f"{node.name}()"
        parts=[f"{node.name}("]
        for it in node.values:
            fv=format_dbg(it, indent+4)
            parts.append(f"{pad_inner}{fv},")
        parts.append(f"{pad})")
        return "\n".join(parts)
    raise TypeError(node)

def type_dbg_node(num):
    if num in INTERPRETED:
        return DVariant(INTERPRETED[num])
    if num in HEARD_OF:
        inner=DVariant("HeardOf",[DLeaf(rust_debug_str(HEARD_OF[num])), DLeaf(str(num))])
        return DVariant("Other",[inner])
    inner=DVariant("UnheardOf",[DLeaf(str(num))])
    return DVariant("Other",[inner])

def class_dbg_node(num):
    if num in CLASS_NAMES:
        return DVariant(CLASS_NAMES[num])
    return DVariant("Other",[DLeaf(str(num))])

