    if val=="always":
        return "Always"
    elif val=="never":
        return "Never"
    else:
        return "Automatic"

def should_colour(mode):
    if mode=="Always": return True
    if mode=="Never": return False
    # Automatic
    if "NO_COLOR" in os.environ: return False
    try:
        return sys.stdout.isatty()
    except Exception:
        return False

