        self.colour_mode="Automatic"
        self.format_durations=True # if --seconds false

    def dbg_node(self):
        domains_dbg=DList([ DStruct("Labels",[("segments", DList([ DTuple([DLeaf(str(len(seg.encode('utf-8')) if False else str(len(seg))), DLeaf(rust_debug_str(seg))]) for seg in lab.segments ]))]) for lab in self.inputs.domains])
        # Note: segment length in Rust debug is (length_byte?) It's the stored length: In Rust segments are (u8, String) where first is byte length of segment string. len(seg) in python characters vs bytes? For ascii same; for punycode ascii same. Use character len? earlier segment "example.net" length 11 chars = bytes. Use len(seg.encode)
        # Correct above: we used len(seg) (characters). For ascii ok. Fix: we need rebuild with byte length
        domains_dbg=DList([])
        for lab in self.inputs.domains:
            seg_list=[]
            for seg in lab.segments:
                seg_list.append(DTuple([DLeaf(str(len(seg.encode('utf-8')))), DLeaf(rust_debug_str(seg))]))
            domains_dbg.items.append(DStruct("Labels",[("segments", DList(seg_list))]))
        inputs_node=DStruct("Inputs",[
            ("domains", domains_dbg),
            ("record_types", DList([type_dbg_node(n) for n in self.inputs.record_types])),
            ("classes", DList([class_dbg_node(n) for n in self.inputs.classes])),
            ("resolver_types", DList([ DVariant("Specific",[DLeaf(rust_debug_str(v))]) if kind=="Specific" else DVariant("SystemDefault") for kind,v in [(r[0], r[1] if len(r)>1 else None) for r in self.inputs.resolvers] ])),
            ("transport_types", DList([DVariant(t) for t in self.inputs.transports])),
        ])
        if self.txid is None:
            txid_node=DVariant("Random")
        else:
            txid_node=DVariant("Sequence",[DLeaf(str(self.txid))])
        req_node=DStruct("RequestGenerator",[
            ("inputs", inputs_node),
            ("txid_generator", txid_node),
            ("edns", DVariant(self.edns)),
            ("protocol_tweaks", DStruct("ProtocolTweaks",[
                ("set_authoritative_flag", DLeaf("true" if self.tweaks_aa else "false")),
                ("set_authentic_flag", DLeaf("true" if self.tweaks_ad else "false")),
                ("set_checking_disabled_flag", DLeaf("true" if self.tweaks_cd else "false")),
                ("udp_payload_size", DVariant("Some",[DLeaf(str(self.bufsize))]) if self.bufsize is not None else DVariant("None")),
            ])),
        ])
        if self.format_kind=="JSON":
            fmt_node=DVariant("JSON")
        elif self.format_kind=="Short":
            fmt_node=DVariant("Short",[DStruct("TextFormat",[("format_durations", DLeaf("true" if self.format_durations else "false"))])])
        else:
            fmt_node=DVariant("Text",[DVariant(self.colour_mode), DStruct("TextFormat",[("format_durations", DLeaf("true" if self.format_durations else "false"))])])
        return DStruct("Options",[
            ("requests", req_node),
            ("measure_time", DLeaf("true" if self.measure_time else "false")),
            ("format", fmt_node),
        ])

