# ---------- DNS Wire ----------
def format_duration(secs, format_durations):
    if not format_durations:
        return str(secs)
    secs=int(secs)
    if secs < 60:
        return f"{secs}s"
    elif secs < 3600:
        return f"{secs//60}m{secs%60:02d}s"
    elif secs < 86400:
        return f"{secs//3600}h{(secs%3600)//60:02d}m{secs%60:02d}s"
    else:
        d=secs//86400; rem=secs%86400
        return f"{d}d{rem//3600}h{(rem%3600)//60:02d}m{rem%60:02d}s"

def escape_text_bytes(data):
    # bytes -> human quoted content (without outer quotes) as per dog
    out=[]
    for b in data:
        if b==34: # "
            out.append('\\"')
        elif b==92:
            out.append('\\\\')
        elif 32 <= b <= 127: # 32..127 inclusive (127 is DEL literal)
            out.append(chr(b))
        else:
            out.append(f"\\{b}")
    return ''.join(out)

def quoted_text_bytes(data):
    return '"'+escape_text_bytes(data)+'"'

def lossy_str(data):
    if isinstance(data, bytes):
        return data.decode('utf-8', errors='replace')
    return data

def labels_to_string(labels):
    # labels list of bytes or str?
    segs=[]
    for lb in labels:
        if isinstance(lb, bytes):
            segs.append(lb.decode('utf-8', errors='replace'))
        else:
            segs.append(lb)
    if not segs:
        return ""
    return ".".join(segs)+"."

class WireError(DogError):
    def __init__(self, msg):
        super().__init__("protocol", f"Malformed packet: {msg}")

class Reader:
    def __init__(self, data):
        self.data=data; self.pos=0
    def remaining(self): return len(self.data)-self.pos
    def read(self, n):
        if n<0 or self.pos+n>len(self.data):
            raise WireError("insufficient data")
        chunk=self.data[self.pos:self.pos+n]; self.pos+=n; return chunk
    def u8(self): return self.read(1)[0]
    def u16(self): return struct.unpack('>H', self.read(2))[0]
    def u32(self): return struct.unpack('>I', self.read(4))[0]
    def read_name(self):
        labels, new_pos, jumps = read_name_at(self.data, self.pos, [])
        self.pos=new_pos
        return labels

def read_name_at(data, start_pos, jumps_arg):
    # recursive implementation for trace logs
    labels=[]
    pos=start_pos
    jumps=list(jumps_arg)
    # We'll implement iterative recursion as function
    def rec(p, jumps_local):
        lbls=[]
        cur=p
        while True:
            if cur>=len(data):
                raise WireError("insufficient data")
            b=data[cur]
            if b==0:
                cur+=1
                return (lbls, cur)
            elif b>=0xC0:
                if cur+1>=len(data):
                    raise WireError("insufficient data")
                target = ((b<<8)|data[cur+1]) - 0xC000
                # target is (u16 - 0xC000)
                if target in jumps_local:
                    raise WireError(f"too much recursion: [{', '.join(str(x) for x in jumps_local)}]")
                jumps_local.append(target)
                if len(jumps_local)>=8:
                    raise WireError(f"too much recursion: [{', '.join(str(x) for x in jumps_local)}]")
                LOG.trace("dns::strings", f"Backtracking to offset {target}")
                suffix, _end = rec(target, jumps_local)
                lbls.extend(suffix)
                LOG.trace("dns::strings", f"Coming back to {cur+2}")
                return (lbls, cur+2)
            else:
                l=b
                if cur+1+l>len(data):
                    raise WireError("insufficient data")
                lbls.append(data[cur+1:cur+1+l])
                cur+=1+l
                continue
    result, new_pos = rec(start_pos, jumps)
    return result, new_pos, jumps

