# Record data representations:
# data is tuple (kind, dict)
# kinds: A, AAAA, NS, CNAME, PTR, SOA, HINFO, MX, TXT, LOC, SRV, NAPTR, SSHFP, TLSA, OPENPGPKEY, EUI48, EUI64, URI, CAA, OPT, Bytes

