# Record data representations:
# data is tuple (kind, dict)
# kinds: A, AAAA, NS, CNAME, PTR, SOA, HINFO, MX, TXT, LOC, SRV, NAPTR, SSHFP, TLSA, OPENPGPKEY, EUI48, EUI64, URI, CAA, OPT, Bytes

def parse_record_data(reader, rtype, rclass, ttl, rdlen, start_pos):
    # start_pos is position at start of rdata in reader
    # Returns data tuple
    # INFO log for interpreted types
    if rtype in INTERPRETED or rtype==41:
        type_name = "OPT" if rtype==41 else INTERPRETED[rtype]
        LOG.info("dns::wire", f"Parsing {type_name} record (type {rtype}, len {rdlen})")
    if rtype==1:
        if rdlen!=4:
            raise WireError(f"record length should be 4, got {rdlen}")
        b=reader.read(4)
        ip=".".join(str(x) for x in b)
        LOG.trace("dns::record::a", f"Parsed IPv4 address -> {ip}")
        return ("A", {"address": ip})
    elif rtype==28:
        if rdlen!=16:
            raise WireError(f"record length should be 16, got {rdlen}")
        b=reader.read(16)
        ip=format_ipv6(b)
        return ("AAAA", {"address": ip})
    elif rtype==2:
        name=reader.read_name()
        return ("NS", {"nameserver_labels": name})
    elif rtype==5:
        name=reader.read_name()
        return ("CNAME", {"domain_labels": name})
    elif rtype==12:
        name=reader.read_name()
        return ("PTR", {"cname_labels": name})
    elif rtype==39:
        # DNAME is heard-of only, generic bytes - handled below
        pass
    elif rtype==6:
        mname=reader.read_name(); rname=reader.read_name()
        serial=reader.u32(); refresh=reader.u32(); retry=reader.u32(); expire=reader.u32(); minimum=reader.u32()
        return ("SOA", {"mname_labels":mname,"rname_labels":rname,"serial":serial,"refresh":refresh,"retry":retry,"expire":expire,"minimum":minimum})
    elif rtype==13:
        cpu=read_character_string(reader); os_=read_character_string(reader)
        return ("HINFO", {"cpu":cpu,"os":os_})
    elif rtype==15:
        pref=reader.u16(); exch=reader.read_name()
        return ("MX", {"preference":pref,"exchange_labels":exch})
    elif rtype==16:
        msgs=[]
        while reader.pos - start_pos < rdlen:
            msgs.append(read_character_string(reader))
        return ("TXT", {"messages":msgs})
    elif rtype==29:
        version=reader.u8()
        if version!=0:
            raise WireError(f"record specifies version {version}, expected up to 0")
        if rdlen!=16:
            raise WireError(f"record length should be 16, got {rdlen}")
        size=reader.u8(); horiz=reader.u8(); vert=reader.u8(); lat=reader.u32(); lon=reader.u32(); alt=reader.u32()
        return ("LOC", {"size_byte":size,"horiz":horiz,"vert":vert,"lat_raw":lat,"lon_raw":lon,"alt_raw":alt})
    elif rtype==33:
        pri=reader.u16(); wei=reader.u16(); port=reader.u16(); target=reader.read_name()
        return ("SRV", {"priority":pri,"weight":wei,"port":port,"target_labels":target})
    elif rtype==35:
        order=reader.u16(); pref=reader.u16(); flags=read_character_string(reader); service=read_character_string(reader); regex=read_character_string(reader); repl=reader.read_name()
        return ("NAPTR", {"order":order,"preference":pref,"flags":flags,"service":service,"regex":regex,"replacement_labels":repl})
    elif rtype==44:
        algo=reader.u8(); fpt=reader.u8()
        if rdlen<3:
            raise WireError(f"record length should be at least 3, got {rdlen}")
        fp=reader.read(rdlen-2)
        return ("SSHFP", {"algorithm":algo,"fingerprint_type":fpt,"fingerprint":fp.hex()})
    elif rtype==52:
        cu=reader.u8(); sel=reader.u8(); mt=reader.u8()
        if rdlen<4:
            raise WireError(f"record length should be at least 4, got {rdlen}")
        cert=reader.read(rdlen-3)
        return ("TLSA", {"certificate_usage":cu,"selector":sel,"matching_type":mt,"certificate_data":cert.hex()})
    elif rtype==61:
        if rdlen<1:
            raise WireError(f"record length should be at least 1, got {rdlen}")
        key=reader.read(rdlen)
        b64=base64.b64encode(key).decode('ascii')
        return ("OPENPGPKEY", {"key":b64})
    elif rtype==108:
        if rdlen!=6:
            raise WireError(f"record length should be 6, got {rdlen}")
        b=reader.read(6)
        ident="-".join(f"{x:02x}" for x in b)
        return ("EUI48", {"identifier":ident})
    elif rtype==109:
        if rdlen!=8:
            raise WireError(f"record length should be 8, got {rdlen}")
        b=reader.read(8)
        ident="-".join(f"{x:02x}" for x in b)
        return ("EUI64", {"identifier":ident})
    elif rtype==256:
        pri=reader.u16(); wei=reader.u16()
        if rdlen<5:
            raise WireError(f"record length should be at least 5, got {rdlen}")
        target=reader.read(rdlen-4)
        return ("URI", {"priority":pri,"weight":wei,"target":target})
    elif rtype==257:
        flag=reader.u8(); tag=read_character_string(reader)
        consumed=reader.pos-start_pos
        remaining=rdlen-consumed
        if remaining<0:
            value=b""
            # let outer length check handle
        else:
            value=reader.read(remaining) if remaining>0 else b""
        critical = (flag & 0x80)!=0
        return ("CAA", {"critical":critical,"tag":tag,"value":value})
    elif rtype==41:
        data_bytes=reader.read(rdlen) if rdlen>0 else b""
        version=(ttl>>16)&0xFF
        return ("OPT", {"udp_size":rclass,"extended_rcode":(ttl>>24)&0xFF,"version":version,"flags":ttl&0xFFFF,"data_bytes":list(data_bytes),"ttl_raw":ttl})
    # generic bytes for other types
    data_bytes=reader.read(rdlen) if rdlen>0 else b""
    return ("Bytes", {"bytes":list(data_bytes)})

def format_ipv6(b):
    segs=struct.unpack('>8H', b)
    # ipv4-mapped
    if segs[0]==0 and segs[1]==0 and segs[2]==0 and segs[3]==0 and segs[4]==0 and segs[5]==0xFFFF:
        ipv4=".".join(str(x) for x in b[12:16])
        return f"::ffff:{ipv4}"
    # find longest run of 0 >=2
    best_start=-1; best_len=0
    i=0
    while i<8:
        if segs[i]==0:
            j=i
            while j<8 and segs[j]==0: j+=1
            run=j-i
            if run>best_len:
                best_len=run; best_start=i
            i=j
        else:
            i+=1
    if best_len<2:
        return ":".join(f"{s:x}" for s in segs)
    left=":".join(f"{s:x}" for s in segs[:best_start])
    right=":".join(f"{s:x}" for s in segs[best_start+best_len:])
    if left and right:
        return f"{left}::{right}"
    elif left:
        return f"{left}::"
    elif right:
        return f"::{right}"
    else:
        return "::"

def parse_response(data_bytes):
    LOG.info("dns::wire", "Parsing response")
    LOG.trace("dns::wire", f"Bytes -> [{', '.join(str(b) for b in data_bytes)}]")
    reader=Reader(data_bytes)
    resp=Response()
    # header
    resp.txid=reader.u16(); LOG.trace("dns::wire", f"Read txid -> {resp.txid}")
    flags_val=reader.u16()
    resp.flags_raw=flags_val
    resp.response_flag=bool(flags_val & 0x8000)
    resp.opcode=(flags_val>>11)&0xF
    resp.authoritative=bool(flags_val & 0x0400)
    resp.truncated=bool(flags_val & 0x0200)
    resp.recursion_desired=bool(flags_val & 0x0100)
    resp.recursion_available=bool(flags_val & 0x0080)
    resp.authentic=bool(flags_val & 0x0020)
    resp.checking_disabled=bool(flags_val & 0x0010)
    resp.rcode=flags_val & 0xF
    LOG.trace("dns::wire", f"Read flags -> {resp.flags_debug()}")
    qd=reader.u16(); an=reader.u16(); ns=reader.u16(); ar=reader.u16()
    LOG.debug("dns::wire", f"Reading {qd}x query from response")
    for _ in range(qd):
        name=reader.read_name()
        qtype=reader.u16()
        LOG.trace("dns::wire", f"Read qtype number -> {qtype}")
        LOG.trace("dns::wire", f"Found qtype -> {type_repr_debug(qtype) if qtype not in (41,) else type_repr_debug(qtype)}")
        # Note for OPT qtype, repr is UnheardOf as per earlier
        if qtype==41:
            # trace found uses UnheardOf - type_repr_debug already gives that
            pass
        qclass=reader.u16()
        LOG.trace("dns::wire", f"Read qclass -> {type_repr_debug(qtype) if qtype!=41 else 'Other(UnheardOf(41))'}")
        resp.queries.append(Query(name,qtype,qclass))
    for count, section_name, dest in [(an,"answer",resp.answers),(ns,"authority",resp.authorities),(ar,"additional answer",resp.additionals)]:
        LOG.debug("dns::wire", f"Reading {count}x {section_name} from response")
        for _ in range(count):
            name=reader.read_name()
            rtype=reader.u16()
            LOG.trace("dns::wire", f"Read qtype number -> {rtype}")
            LOG.trace("dns::wire", f"Found qtype -> {type_repr_debug(rtype) if rtype!=41 else 'Other(UnheardOf(41))'}")
            rclass=reader.u16()
            LOG.trace("dns::wire", f"Read qclass -> {type_repr_debug(rtype) if rtype!=41 else 'Other(UnheardOf(41))'}")
            ttl=reader.u32(); LOG.trace("dns::wire", f"Read TTL -> {ttl}")
            rdlen=reader.u16(); LOG.trace("dns::wire", f"Read record length -> {rdlen}")
            start=reader.pos
            data_tuple=parse_record_data(reader, rtype, rclass, ttl, rdlen, start)
            read_len=reader.pos-start
            if read_len!=rdlen:
                raise WireError(f"length {rdlen} was specified, but read {read_len} bytes")
            dest.append(Record(name, rtype, rclass, ttl, data_tuple))
    return resp

def build_query(labels, qtype, qclass, txid, options):
    flags=0x0100
    if options.tweaks_aa: flags|=0x0400
    if options.tweaks_ad: flags|=0x0020
    if options.tweaks_cd: flags|=0x0010
    edns_disabled = (options.edns=="Disable")
    arcount=0 if edns_disabled else 1
    pkt=struct.pack('>HHHHHH', txid, flags, 1,0,0,arcount)
    for seg in labels.segments:
        b=seg.encode('utf-8')
        pkt+=bytes([len(b)])+b
    pkt+=b'\x00'
    pkt+=struct.pack('>HH', qtype, qclass)
    if not edns_disabled:
        bufsize=options.bufsize if options.bufsize is not None else 512
        pkt+=b'\x00'+struct.pack('>HHIH',41,bufsize,0,0)
    return pkt

