# ---------- Record formatting ----------
def loc_format_point(raw, is_lat):
    center=2147483648
    v=raw-center
    if is_lat:
        maxv=90*3600000; dir_pos="N"; dir_neg="S"
    else:
        maxv=180*3600000; dir_pos="E"; dir_neg="W"
    if abs(v)>maxv:
        return None
    direction=dir_pos if v>=0 else dir_neg
    total=abs(v)
    deg=total//3600000; rem=total%3600000
    minutes=rem//60000; rem2=rem%60000
    sec_int=rem2//1000; sec_frac=rem2%1000
    if sec_frac==0:
        sec_str=str(sec_int)
    else:
        sec_str=f"{sec_int}.{sec_frac:03d}"
    return f"{deg}\u00b0{minutes}\u2032{sec_str}\u2033 {direction}"

def loc_altitude(alt_raw):
    cm=alt_raw-10000000
    # Rust integer division truncates toward zero
    def trunc_div(a,b):
        return int(a/b) if (a% b==0 or (a>=0)) else -(abs(a)//b) if False else int(a/b)  # python int(a/b) float? Use trunc
    # int division trunc toward zero in python: math.trunc
    import math
    metres=math.trunc(cm/100)
    rem=cm - metres*100  # in Rust % has sign of dividend
    if rem==0:
        return f"{metres}m"
    else:
        # format "{}.{:02}m" - Rust {:02} for negative numbers includes sign
        rem_str = format(rem, '02d')  # python format -1 as '-1' (width2), 5 as '05', -50 as '-50'
        return f"{metres}.{rem_str}m"

def record_data_human(rec, format_durations):
    kind, fields = rec.data
    if kind=="A" or kind=="AAAA":
        return fields["address"]
    if kind=="NS":
        return quoted_text_bytes(labels_to_string(fields["nameserver_labels"]).encode('utf-8')) if False else f'"{labels_to_string(fields["nameserver_labels"])}"'
    if kind=="CNAME":
        return f'"{labels_to_string(fields["domain_labels"])}"'
    if kind=="PTR":
