# ---------- Nameserver resolution (Rust std emulation) ----------
def gai_error_str(e):
    # socket.gaierror : args (errno, strerror)
    if isinstance(e, socket.gaierror):
        # python strerror attribute ? gaierror has .strerror
        msg=getattr(e, 'strerror', None) or (e.args[1] if len(e.args)>1 else str(e))
        return f"failed to lookup address information: {msg}"
    return str(e)

def format_os_error(e):
    if isinstance(e, socket.gaierror):
        return gai_error_str(e)
    if isinstance(e, OSError) and e.errno is not None:
        return f"{e.strerror} (os error {e.errno})"
    return str(e)

def parse_socket_addr_str(s):
    # try parse SocketAddr: IPv4:port, [IPv6]:port
    # Returns (ip_str, port) or None
    try:
        if s.startswith('['):
            # [ip]:port
            end=s.find(']')
            if end==-1: return None
            ip=s[1:end]; rest=s[end+1:]
            if not rest.startswith(':'): return None
            port_str=rest[1:]
            port=rust_u16_parse(port_str)
            # Rust SocketAddr parsing: port must be decimal? SocketAddr parse rejects "+port"? Let's approximate: it uses u16 from_str (allows +). Use rust parser
            if port is None: return None
            # validate ip v6
            ipaddress.IPv6Address(ip)
            return (ip, port)
        else:
            # IPv4:port
            if s.count(':')!=1: return None
            host,port_str=s.rsplit(':',1)
            port=rust_u16_parse(port_str)
            if port is None: return None
            ipaddress.IPv4Address(host)
            return (host, port)
    except Exception:
        return None

def rust_str_to_socket_addrs(s):
    # returns list of (ip_str,port,family) or raises DogError(network, msg)
    parsed=parse_socket_addr_str(s)
    if parsed is not None:
        ip,port=parsed
        fam=socket.AF_INET6 if ':' in ip else socket.AF_INET
        return [(ip,port,fam)]
    # split at last colon
    if ':' not in s:
        raise DogError("network","invalid socket address")
    host, port_str = s.rsplit(':',1)
    port=rust_u16_parse(port_str)
    if port is None:
        raise DogError("network","invalid port value")
    # if host parses as IP
    try:
        ipobj=ipaddress.ip_address(host)
        fam=socket.AF_INET6 if ipobj.version==6 else socket.AF_INET
        return [(host,port,fam)]
    except Exception:
        pass
    # DNS lookup host/port : Rust uses getaddrinfo(host, port_str ...) ??? It uses ??? service as port number
    try:
        infos=socket.getaddrinfo(host, port, socket.AF_UNSPEC, socket.SOCK_STREAM)
    except socket.gaierror as e:
        raise DogError("network", gai_error_str(e))
    except Exception as e:
        raise DogError("network", format_os_error(e))
    result=[]
