# HTTPS transport
class BufferedStream:
    def __init__(self, sock):
        self.sock=sock; self.buf=bytearray()
    def recv_more(self):
        try:
            chunk=self.sock.recv(8192)
        except ssl.SSLEOFError:
            return b''
        except (ConnectionResetError, BrokenPipeError) as e:
            raise DogError("network", format_os_error(e))
        except ssl.SSLError as e:
            raise map_tls_error(e)
        except OSError as e:
            raise DogError("network", format_os_error(e))
        if chunk:
            self.buf.extend(chunk)
        return chunk
    def fill_until(self, needle):
        while needle not in self.buf:
            chunk=self.recv_more()
            if chunk==b'':
                # original busy-loops / hangs
                while True: time.sleep(3600)
    def take_buffered(self):
        data=bytes(self.buf); self.buf.clear(); return data

