# ---------- Output formatting ----------
def print_json_output(responses, duration_ms):
    global CURRENT_OPTIONS
    resp_objs=[response_to_json(r) for r in responses]
    top={"responses":resp_objs}
    if CURRENT_OPTIONS.measure_time:
        top["duration"]={"secs": duration_ms//1000, "millis": duration_ms%1000}
    out_write(json_escape_obj(top)+"\n")

def print_text_output(responses, duration_ms, colour):
    global CURRENT_OPTIONS
    # status lines first
    status_prefix=[]
    for r in responses:
        if r.rcode!=0:
            if r.rcode==1: msg="Format Error"
            elif r.rcode==2: msg="Server Failure"
            elif r.rcode==3: msg="NXDomain"
            elif r.rcode==4: msg="Not Implemented"
            elif r.rcode==5: msg="Query Refused"
            else: msg=f"Other Failure ({r.rcode})"
            status_prefix.append(f"Status: {msg}")
    rows=[]
    for resp in responses:
        for section, marker in [("answers",""),("authorities","A"),("additionals","+")]:
            records=filter_records(getattr(resp, section))
            for rec in records:
                tstr=record_type_string(rec)
                name=rec.name_str()
                if rec.rtype==41:
                    ttl_str=""
                else:
                    ttl_str=format_duration(rec.ttl, CURRENT_OPTIONS.format_durations)
                data_str=record_data_human(rec, CURRENT_OPTIONS.format_durations)
                rows.append((tstr,name,ttl_str,marker,data_str))
    lines=[]
    lines.extend(status_prefix)
    if rows:
        max_type=max(len(r[0]) for r in rows)
        max_name=max(len(r[1]) for r in rows)
        max_ttl=max(len(r[2]) for r in rows)
        # width is characters; for non-ascii name, python len is chars, Rust?? We'll use char length
        for tstr,name,ttl_str,marker,data_str in rows:
            # Build padded plain-data for alignment spaces
            type_pad_left=' '*(max_type-len(tstr))
            name_padded=name + ' '*(max_name-len(name))
            ttl_pad_left=' '*(max_ttl-len(ttl_str))
            if colour:
                type_disp=type_pad_left+colorize_type(tstr)
                name_disp=f"\x1b[1;34m{name}\x1b[0m"+' '*(max_name-len(name))
                ttl_disp=ttl_pad_left+ttl_str
                if marker=="A": marker_disp="\x1b[36mA\x1b[0m"
                elif marker=="+": marker_disp="\x1b[32m+\x1b[0m"
                else: marker_disp=" "
                line=f"{type_disp} {name_disp} {ttl_disp} {marker_disp} {data_str}"
            else:
                line=f"{type_pad_left}{tstr} {name_padded} {ttl_pad_left}{ttl_str} {marker if marker else ' '} {data_str}"
            lines.append(line)
    if CURRENT_OPTIONS.measure_time:
        lines.append(f"Ran in {duration_ms}ms")
    if lines:
        out_write("\n".join(lines)+"\n")

def print_short_output(responses):
    lines=[]
    for resp in responses:
        for rec in filter_records(resp.answers):
            lines.append(record_data_human(rec, CURRENT_OPTIONS.format_durations))
    if lines:
        out_write("\n".join(lines)+"\n")
    return len(lines)

def print_error(e):
    global CURRENT_OPTIONS
    if CURRENT_OPTIONS is not None and CURRENT_OPTIONS.format_kind=="JSON":
        # JSON error to stderr, but if format is JSON and also short overrides? format_kind will be Short in that case, not JSON
        err_obj={"error":True,"error_phase":e.phase,"error_message":e.message}
        err_write(json_escape_obj(err_obj)+"\n")
    else:
        # system errors? phase 'system' handling is outside
        err_write(f"Error [{e.phase}]: {e.message}\n")

# ---------- Main ----------
def main(argv_bytes):
    # Non-utf8 pre-scan
    args_str=[]
    for b in argv_bytes:
        try:
            s=b.decode('utf-8')
            args_str.append(s)
        except UnicodeDecodeError:
            err_write(f"dog: Invalid options: Unrecognized option: '{osstring_debug(b)}'\n")
            return 3
    # getopts
    try:
        opts=parse_getopts(args_str)
    except OptionsError as e:
        err_write(f"dog: Invalid options: {e}\n")
        return 3
    # defs
    help_def=def_by_long('help'); version_def=def_by_long('version')
    colour_mode=colour_mode_from_opts(opts)
    use_colour=should_colour(colour_mode)
    if opts.present(version_def):
        out_write(version_coloured() if use_colour else VERSION_TEXT_PLAIN)
        return 0
    if opts.present(help_def):
        out_write(colourise_help() if use_colour else HELP_TEXT_PLAIN)
        return 0
    # Build options in validation order
    options=Options()
    options.colour_mode=colour_mode
    global CURRENT_OPTIONS
    CURRENT_OPTIONS=options
    # EDNS
    edns_def=def_by_long('edns')
    if opts.present(edns_def):
        v=opts.opt_str(edns_def)
        if v=="disable": options.edns="Disable"
        elif v=="hide": options.edns="SendAndHide"
