def print_text_output(responses, duration_ms, colour):
    global CURRENT_OPTIONS
    # status lines first
    status_prefix=[]
    for r in responses:
        if r.rcode!=0:
            if r.rcode==1: msg="Format Error"
            elif r.rcode==2: msg="Server Failure"
            elif r.rcode==3: msg="NXDomain"
            elif r.rcode==4: msg="Not Implemented"
            elif r.rcode==5: msg="Query Refused"
            else: msg=f"Other Failure ({r.rcode})"
            status_prefix.append(f"Status: {msg}")
    rows=[]
    for resp in responses:
        for section, marker in [("answers",""),("authorities","A"),("additionals","+")]:
            records=filter_records(getattr(resp, section))
            for rec in records:
                tstr=record_type_string(rec)
                name=rec.name_str()
                if rec.rtype==41:
                    ttl_str=""
                else:
                    ttl_str=format_duration(rec.ttl, CURRENT_OPTIONS.format_durations)
                data_str=record_data_human(rec, CURRENT_OPTIONS.format_durations)
                rows.append((tstr,name,ttl_str,marker,data_str))
    lines=[]
    lines.extend(status_prefix)
    if rows:
        max_type=max(len(r[0]) for r in rows)
        max_name=max(len(r[1]) for r in rows)
        max_ttl=max(len(r[2]) for r in rows)
        # width is characters; for non-ascii name, python len is chars, Rust?? We'll use char length
        for tstr,name,ttl_str,marker,data_str in rows:
            # Build padded plain-data for alignment spaces
            type_pad_left=' '*(max_type-len(tstr))
            name_padded=name + ' '*(max_name-len(name))
            ttl_pad_left=' '*(max_ttl-len(ttl_str))
            if colour:
                type_disp=type_pad_left+colorize_type(tstr)
                name_disp=f"\x1b[1;34m{name}\x1b[0m"+' '*(max_name-len(name))
                ttl_disp=ttl_pad_left+ttl_str
                if marker=="A": marker_disp="\x1b[36mA\x1b[0m"
                elif marker=="+": marker_disp="\x1b[32m+\x1b[0m"
                else: marker_disp=" "
                line=f"{type_disp} {name_disp} {ttl_disp} {marker_disp} {data_str}"
            else:
                line=f"{type_pad_left}{tstr} {name_padded} {ttl_pad_left}{ttl_str} {marker if marker else ' '} {data_str}"
            lines.append(line)
    if CURRENT_OPTIONS.measure_time:
        lines.append(f"Ran in {duration_ms}ms")
    if lines:
        out_write("\n".join(lines)+"\n")

