import sys, random, struct, subprocess
sys.path.insert(0,'/tmp')
from harness import *
ORIG="./executable"; MINE="/tmp/mydog"
def handler(q):
    # qname is t< trial >.example
    try:
        trial=int(q['qname'].split('.')[0][1:])
    except:
        trial=0
    rnd=random.Random(trial*999+7)
    flags=0x8000 | rnd.choice([0,0x100,0x80,0x780]) | rnd.randint(0,15)
    sections=[]; counts=[]
    for sec_i in range(3):
        recs=[]; n=rnd.randint(0,3); counts.append(n)
        for i in range(n):
            rtype=rnd.choice([1,2,5,6,12,13,15,16,28,29,33,35,44,52,61,99,257,256,108,41,17,108,109])
            if rnd.random()<0.5:
                rdata=bytes(rnd.randint(0,255) for _ in range(rnd.randint(0,20)))
            else:
                if rtype==1: rdata=socket.inet_aton('1.2.3.4')
                elif rtype==28: rdata=socket.inet_pton(socket.AF_INET6,'2001:db8::1')
                elif rtype==16: rdata=b'\x03abc\x02de'
                elif rtype==5: rdata=encode_name("x.example")
                elif rtype==29: rdata=bytes([0,0x12,1,2])+struct.pack('>III', rnd.randint(0,4294967295), rnd.randint(0,4294967295), rnd.randint(0,4294967295))
                else: rdata=bytes(rnd.randint(0,255) for _ in range(rnd.randint(0,10)))
            recs.append(rr(PTR,rtype,rnd.choice([1,3,4,99]),rnd.choice([0,60,300,86400,4294967295]),rdata))
        sections.append(recs)
    resp=struct.pack('>HHHHHH',q['txid'],flags,1,counts[0],counts[1],counts[2])+q['question_bytes']
    for sec in sections:
        for r in sec: resp+=r
    return resp

fails=0; total=0
with Server(handler, port=15458) as srv:
    for trial in range(200):
        for args_template in [[f"t{trial}.example","@127.0.0.1:15458"],[f"t{trial}.example","@127.0.0.1:15458","-J"],[f"t{trial}.example","@127.0.0.1:15458","-1"],[f"t{trial}.example","@127.0.0.1:15458","--edns=show","--color=always"],[f"t{trial}.example","@127.0.0.1:15458","--seconds","-1"]]:
            total+=1
            a=subprocess.run([ORIG]+args_template,capture_output=True,timeout=5)
            b=subprocess.run([MINE]+args_template,capture_output=True,timeout=5)
            ra=(a.returncode,a.stdout,a.stderr); rb=(b.returncode,b.stdout,b.stderr)
            if ra!=rb:
                fails+=1; print("DIFF",args_template); print(" orig",ra); print(" mine",rb)
                if fails>10: break
        if fails>10: break
print("total",total,"fails",fails)
PY
timeout 120 python3 /tmp/test_fuzz_fast.py; echo rc:$?"}

